{
  "title": "screenshot_watchdog_capturebeyond_bool",
  "request": "hey, the ScreenshotWatchdog passes the full_page flag straight to CDP which can be None. can we coerce it to a bool so it becomes False when not set? update the params dict in on_ScreenshotEvent.",
  "edits": [
    {
      "path": "browser_use/browser/watchdogs/screenshot_watchdog.py",
      "search": "			params_dict: dict[str, Any] = {'format': 'png', 'captureBeyondViewport': event.full_page}",
      "replace": "			params_dict: dict[str, Any] = {'format': 'png', 'captureBeyondViewport': bool(event.full_page)}"
    }
  ],
  "test_path": "tests/test_screenshot_watchdog_capturebeyond.py",
  "test": "import pytest

from browser_use.browser.watchdogs.screenshot_watchdog import ScreenshotWatchdog

class DummyTarget:
    target_type = 'page'
    target_id = 't1'

class DummyCdpSession:
    def __init__(self):
        self.session_id = 'sess'
        self.last_params = None
        class Page:
            async def captureScreenshot(inner_self, params, session_id):
                # Store params on outer session for later inspection
                self.last_params = params
                return {'data': 'dummy'}
        class Send:
            Page = Page()
        self.cdp_client = type('Client', (), {'send': Send()})()

class DummyBrowserSession:
    def __init__(self):
        self.cdp_session = DummyCdpSession()
    def get_focused_target(self):
        return DummyTarget()
    def get_page_targets(self):
        return []
    async def get_or_create_cdp_session(self, target_id, focus):
        return self.cdp_session
    async def remove_highlights(self):
        pass

class DummyEvent:
    def __init__(self, full_page=None, clip=None):
        self.full_page = full_page
        self.clip = clip

@pytest.mark.asyncio
async def test_captureBeyondViewport_is_bool(monkeypatch):
    # Replace CaptureScreenshotParameters with a simple container that stores kwargs
    class DummyParams:
        def __init__(self, **kwargs):
            self.__dict__.update(kwargs)
    monkeypatch.setattr('browser_use.browser.watchdogs.screenshot_watchdog.CaptureScreenshotParameters', DummyParams)

    watchdog = ScreenshotWatchdog()
    watchdog.browser_session = DummyBrowserSession()
    # Provide a minimal logger with the expected methods
    watchdog.logger = type('L', (), {
        'debug': lambda *a, **kw: None,
        'warning': lambda *a, **kw: None,
        'error': lambda *a, **kw: None,
    })()

    event = DummyEvent(full_page=None, clip=None)
    await watchdog.on_ScreenshotEvent(event)

    captured = watchdog.browser_session.cdp_session.last_params
    assert captured is not None, "CaptureScreenshotParameters was not passed"
    # The captureBeyondViewport flag should be False when the event.full_page is None
    assert getattr(captured, 'captureBeyondViewport') is False
